(ns fastmath.signal.test-signals-test
  (:require [fastmath.signal.test-signals :as sut]
            [clojure.test :as t]
            [clojure.java.io :as io]
            [clojure.edn :as edn]))

;; WaveLab MakeSignal formulas at t = (1..1024)/1024, generated by
;; `utils/fastmath/dev/generate_test_signals_reference.py` into
;; `test/resources/signal/test_signals_reference.edn`.

(def ^:private reference
  (delay (edn/read-string (slurp (io/resource "signal/test_signals_reference.edn")))))

(defn- max-diff
  [a b]
  (reduce max 0.0 (map #(Math/abs (- (double %1) (double %2))) a b)))

(t/deftest signals-vs-wavelab
  (let [{:keys [t] :as r} @reference
        t- (butlast t)]
    (doseq [[k f] {:blocks sut/blocks :heavisine sut/heavisine :doppler sut/doppler}]
      (t/is (<= (max-diff (r k) (map f t)) 1.0e-14) (str k)))
    ;; bumps at t = 1 is the value at t = 0 (period 1), WaveLab evaluates the formula at 1
    (t/is (<= (max-diff (butlast (:bumps r)) (map sut/bumps t-)) 1.0e-14) "bumps below t = 1")
    (t/is (= (sut/bumps 0.0) (sut/bumps 1.0)))))

(t/deftest periodic
  (doseq [f [sut/blocks sut/bumps sut/heavisine sut/doppler]]
    (t/is (every? (fn [t] (< (Math/abs (- (f t) (f (+ t 1.0)))) 1.0e-12))
                  (map #(- (* 0.0371 %) 2.0) (range 50))))))
